import pandas as pd


def conversion_by_arm(users: pd.DataFrame) -> dict[str, float]:
    """Conversion rate per assigned arm. One row per randomised user."""
    analysed = users[(users["arm"] == "A") | users["saw_new_page"]]
    return analysed.groupby("arm")["converted"].mean().to_dict()

